ee:message.ee:set-payload:
%dw 2.0
output application/json
fun buildRecipient(recipient, channel) = {
    customerId: recipient.customerId,
    (emailAddress: recipient.emailAddress) if (channel == "EMAIL"),
    (mobileNumber: recipient.mobileNumber) if (channel == "SMS"),
    listName: {
        folderName:  recipient.listFolderName,
        objectName:  recipient.listObjectName
    }
}

fun buildOptionalData(optionalData) =
    optionalData map {
        name:  $.name,
        value: $.value as String
    }
---
{
    recipientData: payload.recipients map (recipient) -> {
        recipient:    buildRecipient(recipient, payload.channel),
        optionalData: buildOptionalData(recipient.optionalData default [])
    }
}
